- Could you support variable window sizes per key if needed?
- What memory bounds exist, and how could you proactively prune empty keys?

## Why This Is Asked
Tests DP with dual objectives: minimize cost and count optimal deletion sets, plus implement in two styles. It also covers edge cases like empty substrings and ties.

## Key Concepts
- DP on substrings; store (cost, ways).
- Memoization and bottom-up parallels; careful counting on ties.
- Modulo arithmetic for counts.

## Code Example
```javascript
// Memoized DFS
function solveMemo(s, delCost){
  const n = s.length;
  const memoCost = Array.from({length:n},()=>Array(n).fill(-1));
  const memoWays = Array.from({length:n},()=>Array(n).fill(0));
  const MOD = 1_000_000_007;
  function dfs(l,r){
    if (l>=r) return {cost:0, ways:1};
    if (memoCost[l][r]!==-1) return {cost:memoCost[l][r], ways:memoWays[l][r]};
    if (s[l]===s[r]){
      const res = dfs(l+1,r-1);
      memoCost[l][r]=res.cost;
      memoWays[l][r]=res.ways;
      return res;
    } else {
      const A = dfs(l+1,r);
      const B = dfs(l,r-1);
      let cost;
      let ways = 0;
      if (A.cost + delCost[l] < B.cost + delCost[r]){
        cost = A.cost + delCost[l];
        ways = A.ways;
      } else if (B.cost + delCost[r] < A.cost + delCost[l]){
        cost = B.cost + delCost[r];
        ways = B.ways;
      } else {
        cost = A.cost + Math.min(delCost[l], delCost[r]);
        ways = (A.ways + B.ways) % MOD;
      }
      memoCost[l][r]=cost; memoWays[l][r]=ways;
      return {cost, ways};
    }
  }
  return dfs(0,n-1);
}
```

## Why This Is Asked
Tests a practical streaming pattern: sliding window analytics with per-user deduplication per category, real-time top-K, and lazy expirations to avoid full scans.

## Key Concepts
- Sliding window with expirations
- Hash table for lastEvent per (user_id, category)
- Per-category max-heap with lazy deletions
- Global category-score heap for top-K queries

## Code Example
```javascript
class QuickCategoryGrouper {
  constructor(W){ this.W=W; this.last=new Map(); this.catSums=new Map(); this.catHeaps=new Map(); this.catTotal=new Map(); }
  addEvent(e){ const key=`${e.user_id}:${e.category}`; const prev=this.last.get(key); if(prev && prev.ts> e.ts-W){ this._applyDelta(e.category, e.value - prev.value); } else { this._applyDelta(e.category, e.value); }
    this.last.set(key,{value:e.value, ts:e.ts}); this._pushToHeap(e.category,{value:e.value, user:e.user_id, ts:e.ts}); }
  _applyDelta(cat, delta){ this.catTotal.set(cat,(this.catTotal.get(cat)||0)+delta); }
  _pushToHeap(cat, item){ if(!this.catHeaps.has(cat)) this.catHeaps.set(cat, []); this.catHeaps.get(cat).push(item); }
  topKCategories(K, currentTime){ // lazy pop to ensure validity
    const res=[]; for(const [cat, total] of this.catTotal){ res.push({cat, total}); }
    res.sort((a,b)=> b.total - a.total); return res.slice(0,K).map(r=>r.cat); }
}
```

